package com.talkanything.testevidence.sample.order.protocol;
import org.apache.http.client.methods.CloseableHttpResponse;import org.apache.http.client.methods.HttpGet;import org.apache.http.impl.client.HttpClients;import org.springframework.stereotype.Component;import java.io.IOException;
@Component public class Apache4ProtocolClient implements ProtocolClient { private final ProtocolClientSupport support; public Apache4ProtocolClient(ProtocolClientSupport support){this.support=support;} public String name(){return "apache4";} public ProtocolEchoResponse invoke(ProtocolInvocation r){try(var c=HttpClients.createDefault(); CloseableHttpResponse x=c.execute(new HttpGet(support.uri(r)))){return support.read(x.getStatusLine().getStatusCode(),x.getEntity().getContent());}catch(IOException e){throw new IllegalStateException(e);}}}